    T = data[3]
    rows = data[4:4+H]
    land = np.array([[c == '.' for c in r] for r in rows], dtype=bool)
    valid = land.copy()
    di = 0; dj = 0
    def apply(valid, di, dj):
        # cond[i,j] = land[i+di, j+dj] if in range else False
        cond = np.zeros((H, W), dtype=bool)
        i0 = max(0, -di); i1 = min(H, H - di)
        j0 = max(0, -dj); j1 = min(W, W - dj)
        if i0 < i1 and j0 < j1:
            cond[i0:i1, j0:j1] = land[i0+di:i1+di, j0+dj:j1+dj]
        return valid & cond
