DIRS = {'L': (0, -1), 'R': (0, 1), 'U': (-1, 0), 'D': (1, 0)}


def _parse(inp):
    t = inp.split()
    H, W, N = int(t[0]), int(t[1]), int(t[2])
    T = t[3]
    S = t[4:4 + H]
    return H, W, N, T, S


@st.composite
def gen(draw):
    H = draw(st.integers(4, 6))
    W = draw(st.integers(4, 6))
    N = draw(st.integers(1, 6))
    # Interior region rows 1..H-2, cols 1..W-2
    r = draw(st.integers(1, H - 2))
    c = draw(st.integers(1, W - 2))
    grid = [[('#' if (i == 0 or i == H - 1 or j == 0 or j == W - 1) else None)
             for j in range(W)] for i in range(H)]
    for i in range(1, H - 1):
        for j in range(1, W - 1):
            grid[i][j] = '.' if draw(st.booleans()) else '#'
    # Build a walk staying inside the interior so that the start is a candidate.
    walk_cells = [(r, c)]
    T = []
    cr, cc = r, c
    for _ in range(N):
        opts = []
        for ch, (dr, dc) in DIRS.items():
            nr, nc = cr + dr, cc + dc
            if 1 <= nr <= H - 2 and 1 <= nc <= W - 2:
                opts.append(ch)
        ch = draw(st.sampled_from(opts))
        dr, dc = DIRS[ch]
        cr, cc = cr + dr, cc + dc
        T.append(ch)
        walk_cells.append((cr, cc))
    for (i, j) in walk_cells:
        grid[i][j] = '.'
    rows = [''.join(row) for row in grid]
    return f"{H} {W} {N}\n{''.join(T)}\n" + "\n".join(rows) + "\n"


