                cur.add((i, j))
    for ch in T:
        dr, dc = DIRS[ch]
        cur = {(i + dr, j + dc) for (i, j) in cur}
        cur = {(i, j) for (i, j) in cur
               if 0 <= i < H and 0 <= j < W and S[i][j] == '.'}
    return str(len(cur))


